-- Dataset: Portfolio Quality KPIs
-- Page: Delinquency and Portfolio Quality
-- Connection: CREDIT_PORTFOLIO | Mode: Direct
-- Parameters: p_date_key = October 2026 (Text), p_product_id = All Products (Text), p_region_id = All Regions (Text), p_channel_id = All Channels (Text), p_min_dpd = 1+ DPD (Text)

WITH bounds AS (SELECT (SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date) AS as_of_date,
      (date_trunc('month',(SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date))-interval '1 day')::date AS previous_date,
      date_trunc('month',(SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date))::date AS month_start),
    current_rows AS (SELECT s.* FROM credit.v_snapshot s CROSS JOIN bounds b
      WHERE s.snapshot_date=b.as_of_date AND (${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}=0 OR s.product_id=${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}) AND (${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}=0 OR s.region_id=${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}) AND (${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))}=0 OR s.channel_id=${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))})), eligible AS (SELECT * FROM current_rows WHERE principal_balance>0
      AND loan_status='Active' AND dpd>=greatest(${IF(p_min_dpd="All active",0,IF(p_min_dpd="1+ DPD",1,IF(p_min_dpd="31+ DPD",31,IF(p_min_dpd="91+ DPD",91,INT(p_min_dpd)))))},0)),
    registry_counts AS (SELECT count(*) AS registry_total FROM eligible), summary AS (
      SELECT coalesce(sum(principal_balance),0) AS portfolio_balance,
        coalesce(sum(overdue_principal),0) AS overdue_principal,
        coalesce(sum(overdue_interest),0) AS overdue_interest,
        coalesce(sum(principal_balance) FILTER(WHERE dpd>=31),0) AS exposure_31_plus,
        coalesce(sum(principal_balance) FILTER(WHERE dpd>=91),0) AS exposure_91_plus,
        count(*) FILTER(WHERE principal_balance>0) AS active_loans,
        count(*) FILTER(WHERE principal_balance>0 AND dpd>0) AS past_due_loans
      FROM current_rows),
    writeoffs AS (SELECT coalesce(sum(o.principal_amount),0) AS monthly_writeoffs
      FROM credit.loan_operation o JOIN credit.v_loan_dimension l USING(loan_id) CROSS JOIN bounds b
      WHERE o.operation_type='WRITE_OFF' AND o.operation_date BETWEEN b.month_start AND b.as_of_date AND (${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}=0 OR l.product_id=${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}) AND (${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}=0 OR l.region_id=${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}) AND (${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))}=0 OR l.channel_id=${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))})),
    k AS (SELECT s.*,p.*,b.*,w.*,
      s.exposure_31_plus/nullif(s.portfolio_balance,0) AS dpd_31_plus_ratio,
      s.exposure_91_plus/nullif(s.portfolio_balance,0) AS dpd_91_plus_ratio
      FROM summary s CROSS JOIN registry_counts p CROSS JOIN bounds b CROSS JOIN writeoffs w)
    SELECT k.*,CASE WHEN abs(overdue_principal)>=1000000000 THEN 'RUB '||to_char(overdue_principal/1000000000,'FM999,990.00')||' bn' ELSE 'RUB '||to_char(overdue_principal/1000000,'FM999,990.00')||' m' END AS overdue_principal_label,CASE WHEN abs(overdue_interest)>=1000000000 THEN 'RUB '||to_char(overdue_interest/1000000000,'FM999,990.00')||' bn' ELSE 'RUB '||to_char(overdue_interest/1000000,'FM999,990.00')||' m' END AS overdue_interest_label,
      CASE WHEN abs(monthly_writeoffs)>=1000000000 THEN 'RUB '||to_char(monthly_writeoffs/1000000000,'FM999,990.00')||' bn' ELSE 'RUB '||to_char(monthly_writeoffs/1000000,'FM999,990.00')||' m' END AS writeoff_label,CASE WHEN abs(exposure_31_plus)>=1000000000 THEN 'RUB '||to_char(exposure_31_plus/1000000000,'FM999,990.00')||' bn' ELSE 'RUB '||to_char(exposure_31_plus/1000000,'FM999,990.00')||' m' END||' full-loan exposure' AS exposure31_note,
      CASE WHEN abs(exposure_91_plus)>=1000000000 THEN 'RUB '||to_char(exposure_91_plus/1000000000,'FM999,990.00')||' bn' ELSE 'RUB '||to_char(exposure_91_plus/1000000,'FM999,990.00')||' m' END||' full-loan exposure' AS exposure91_note,
      coalesce(to_char(dpd_31_plus_ratio*100,'FM990.00')||'%','—') AS ratio31_label,
      coalesce(to_char(dpd_91_plus_ratio*100,'FM990.00')||'%','—') AS ratio91_label,
      to_char(past_due_loans,'FM999,990') AS past_due_loans_label,
      to_char(active_loans,'FM999,990')||' active contracts in scope' AS active_loans_note,
      to_char(as_of_date,'DD Mon YYYY') AS date_label,
      to_char(month_start,'Mon YYYY')||' · principal written off' AS writeoff_note,
      to_char(previous_date,'DD Mon YYYY')||' → '||to_char(as_of_date,'DD Mon YYYY')||' · Opening cohort · % and count' AS transition_note,
      CASE WHEN registry_total=0 THEN 'No loans meet the registry threshold.'
        ELSE 'Ordered by DPD, principal balance and loan ID · amounts in RUB' END AS registry_note,
      CASE WHEN active_loans=0 THEN 'No active loans match the selected filters.'
        ELSE 'Full-loan exposure includes overdue principal. Registry threshold affects the loan list only.' END AS scope_note
    FROM k
